#!/usr/bin/env python3
"""Nested selectable cells and observable malformed input through the real app."""
import argparse,json,math
from pathlib import Path
from app_harness import application
p=argparse.ArgumentParser();p.add_argument('--app',required=True);p.add_argument('--output',required=True);a=p.parse_args();out=Path(a.output).resolve()
with application(a.app,out) as (call,transcript):
    def inspect():return call('document.inspect')
    def draft():return call('app.state')['activeSession']['draftSketch']
    call('document.units',{'units':'in'});call('sketch.create',{'plane':'XY','name':'Nested regions — Alloy fixture'})
    call('sketch.rectangle',{'x1':0,'y1':0,'x2':40,'y2':25,'units':'mm'});edges=draft()['parameters']['entities'];call('sketch.constraint',{'type':'fixed','pointIds':[edges[0]['startPointId']]});call('sketch.dimension',{'kind':'horizontal','entityId':edges[0]['id'],'value':40,'units':'mm'});width=draft()['parameters']['dimensions'][-1]['id'];call('sketch.dimension',{'kind':'vertical','entityId':edges[1]['id'],'value':25,'units':'mm'})
    call('sketch.addCircle',{'centerX':20,'centerY':12.5,'diameter':10,'units':'mm'});circle=draft()['parameters']['entities'][-1];call('sketch.dimension',{'kind':'radius','entityId':circle['id'],'value':5,'units':'mm'});radius=draft()['parameters']['dimensions'][-1]['id'];call('sketch.addCircle',{'centerX':20,'centerY':12.5,'diameter':4,'units':'mm'});source=draft();preview=call('command.preview',{'session':call('app.state')['activeSession']['id']});regions=preview['sketchGeometry']['profiles'];assert len(regions)==3
    outer=next(p for p in regions if math.isclose(p['areaMm2'],1000-25*math.pi,abs_tol=1e-6));middle=next(p for p in regions if math.isclose(p['areaMm2'],21*math.pi,abs_tol=1e-6));island=next(p for p in regions if math.isclose(p['areaMm2'],4*math.pi,abs_tol=1e-6));assert outer['innerLoopCount']==middle['innerLoopCount']==1 and island['innerLoopCount']==0;ids={r['profileId'] for r in regions}
    call('capture.screenshot',{'path':str(out/'nested-sketch.png')});call('sketch.finish');call('view.orientation',{'name':'top'});call('view.home');before=inspect();args={'sketchId':source['id'],'profileId':outer['profileId']};s=call('solid.extrudeDialog',args);call('command.update',{'session':s['id'],'inputs':{'distance':5/25.4,'units':'in'}});preview=call('command.preview',{'session':s['id']});assert preview['previewed'];call('command.cancel',{'session':s['id']});assert inspect()['authored']==before['authored'] and inspect()['undo']==before['undo']
    call('solid.extrude',{**args,'distance':5/25.4,'units':'in'});call('solid.extrude',{'sketchId':source['id'],'profileId':island['profileId'],'distance':5/25.4,'units':'in'});accepted=inspect();volumes=sorted(b['volumeMm3'] for b in accepted['evaluation']['bodies']);assert len(volumes)==2 and math.isclose(volumes[0],20*math.pi,abs_tol=1e-5) and math.isclose(volumes[1],5000-125*math.pi,abs_tol=1e-5);call('history.undo');call('history.redo');assert inspect()['authored']==accepted['authored']
    call('sketch.edit',{'sketchId':source['id']});call('sketch.dimensionUpdate',{'dimensionId':width,'value':50,'units':'mm'});call('sketch.dimensionUpdate',{'dimensionId':radius,'value':6,'units':'mm'});call('sketch.finish');edited=inspect();assert {p['profileId'] for p in edited['evaluation']['sketches'][0]['profiles']}==ids;assert math.isclose(max(b['volumeMm3'] for b in edited['evaluation']['bodies']),6250-180*math.pi,abs_tol=1e-5)
    path=out/'nested-regions.alloy';call('document.save',{'path':str(path)});call('document.open',{'path':str(path)});assert inspect()['authored']==edited['authored'];call('view.home');call('capture.screenshot',{'path':str(out/'nested-solids.png')})
    # Observable unused and duplicate sources preserve valid cells.
    call('sketch.edit',{'sketchId':source['id']});call('sketch.line',{'x1':60,'y1':0,'x2':65,'y2':0,'units':'mm'});call('sketch.line',{'x1':50,'y1':0,'x2':0,'y2':0,'units':'mm'});preview=call('command.preview',{'session':call('app.state')['activeSession']['id']});diag=preview['sketchGeometry']['profileDiagnostics'];open_diag=diag;assert len(preview['sketchGeometry']['profiles'])==3 and len(diag['ignoredEntityIds'])==1 and any(n['code']=='coincident_boundary_sources' and len(n['entityIds'])==2 for n in diag['notices']);call('capture.screenshot',{'path':str(out/'open-duplicate-status.png')});call('command.cancel',{'session':call('app.state')['activeSession']['id']});assert inspect()['authored']==edited['authored']
    call('document.new',{'discard':True});call('sketch.create',{'plane':'XY','name':'Separated endpoints — no implicit closure'})
    for points in [(0,0,40,0),(40,0,40,25),(40,25,0,25),(0,25,0,1e-8)]:call('sketch.line',dict(zip(('x1','y1','x2','y2'),points),units='mm'))
    call('sketch.addCircle',{'centerX':20,'centerY':12.5,'diameter':10,'units':'mm'});state=call('app.state');bad=call('command.preview',{'session':state['activeSession']['id']});diag=bad['sketchGeometry']['profileDiagnostics'];assert bad['sketchGeometry']['profiles']==[] and diag['code']=='undeclared_endpoint_merge' and math.isclose(diag['distanceMm'],1e-8,abs_tol=1e-12);call('capture.screenshot',{'path':str(out/'kernel-gap-status.png')});call('sketch.finish');broken=inspect();call('solid.extrude',{'sketchId':broken['authored']['features'][0]['id'],'profileId':outer['profileId'],'distance':5,'units':'mm'},error='evaluation_failed');assert inspect()['authored']==broken['authored'] and inspect()['revision']==broken['revision']
    (out/'report.json').write_text(json.dumps({'passed':True,'scope':'shared API geometry/history/storage/diagnostics; native selection separate','accepted':edited,'openDuplicateDiagnostics':open_diag,'gapDiagnostics':diag},indent=2));(out/'transcript.json').write_text(json.dumps(transcript,indent=2))
